-- Route Moon Priestess Amara and her two huntresses along the owner's recorded
-- Dolanaar walk: leave the road, circle the inn, cross its center aisle, and
-- wait outside the eastern entrance. Reverse the same route on the way back.
-- The two short crossings at the eastern exit need a direct spline because the
-- local navmesh sends a normal waypoint move around the building wall.
ALTER TABLE `creature_movement`
  ADD COLUMN IF NOT EXISTS `straight_path` TINYINT(1) UNSIGNED NOT NULL DEFAULT 0
  COMMENT 'Use a straight spline to this waypoint instead of navmesh pathfinding';

-- Match the patrol's tested spawn and its two escort positions.
UPDATE `creature`
SET `position_x`=9875.29, `position_y`=1083.34, `position_z`=1308.01,
    `orientation`=1.13493, `wander_distance`=0, `movement_type`=2
WHERE `guid`=46394 AND `id`=2151;
UPDATE `creature`
SET `position_x`=9876.32, `position_y`=1080.52, `position_z`=1308.01,
    `orientation`=1.13493, `wander_distance`=0, `movement_type`=0
WHERE `guid`=46414 AND `id`=10604;
UPDATE `creature`
SET `position_x`=9872.47, `position_y`=1082.31, `position_z`=1308.01,
    `orientation`=1.13493, `wander_distance`=0, `movement_type`=0
WHERE `guid`=46416 AND `id`=10606;

-- Leave room for both mounted escorts beside the inn counter.
UPDATE `creature_groups`
SET `dist`=2
WHERE `leader_guid`=46394 AND `member_guid` IN (46414, 46416);

DELETE FROM `creature_movement` WHERE `id` = 46394;
